'use strict';
// Read-only synthetic evidence viewer. Selecting a snapshot is not an execution command.
const tradingCases={
 unknown:{label:['Итог неизвестен','Outcome unknown'],fill:null,reserve:20,cancelled:null,position:null,final:false,fresh:true,consistent:false,copy:false,why:['Нет подтверждения исходной заявки. Сохраняем резерв на возможное исполнение.','Original-order evidence is missing. Reserve remains for possible execution.'],event:['12:00 · Итог не получен. Тайм-аут не доказывает отказ.','12:00 · Outcome unavailable. A timeout does not prove rejection.']},
 partial:{label:['Часть исполнена · ждём отмену','Part filled · cancellation pending'],fill:8,reserve:12,cancelled:0,position:28,final:false,fresh:true,consistent:true,copy:true,why:['Отмена 12 USD запрошена системой, но ещё не подтверждена площадкой. Исполненные 8 USD остаются в позиции.','The system requested cancellation of USD 12; the venue has not confirmed it. The USD 8 fill stays in the position.'],event:['12:00 · Подтверждены 8 USD. Запрошена отмена остатка 12 USD.','12:00 · USD 8 confirmed. Cancellation of the USD 12 remainder requested.']},
 late:{label:['Позднее исполнение · ждём отмену','Late fill · cancellation pending'],fill:12,reserve:8,cancelled:0,position:32,final:false,fresh:true,consistent:true,copy:true,why:['Дополнительно подтверждены 4 USD той же заявки. Резерв уменьшился до 8 USD; доступные средства не выросли.','Another USD 4 of the same order is confirmed. Reserve is now USD 8; available funds did not increase.'],event:['12:01 · FILL-005-B: +4 USD. Повтор этого подтверждения не создаёт второй покупки.','12:01 · FILL-005-B: +USD 4. Repeated delivery does not create a second purchase.']},
 cancelled:{label:['Остаток отменён','Remainder cancelled'],fill:12,reserve:0,cancelled:8,position:32,final:true,fresh:true,consistent:true,copy:true,why:['Подтверждена отмена оставшихся 8 USD: их резерв освобождён. Покупка 12 USD остаётся в учёте.','Cancellation of the remaining USD 8 is confirmed: its reserve is released. The USD 12 purchase stays recorded.'],event:['12:02 · CANCEL-005-C: окончательная отмена 8 USD после двух подтверждённых частей.','12:02 · CANCEL-005-C: final cancellation of USD 8 after two confirmed fills.']},
 full:{label:['Исполнено полностью · отмена не успела','Fully filled · cancellation was too late'],fill:20,reserve:0,cancelled:0,position:40,final:true,fresh:true,consistent:true,copy:true,why:['Вместо отмены подтверждены все 20 USD. Остатка и его резерва нет; отменённого объёма тоже нет.','All USD 20 filled before cancellation. No remainder or remainder reserve; no cancelled amount.'],event:['12:02 · FILL-005-F: итоговое исполнение 20 USD.','12:02 · FILL-005-F: total confirmed fill USD 20.']},
 conflict:{label:['Противоречивые подтверждения','Conflicting evidence'],fill:12,reserve:8,cancelled:null,position:32,final:false,fresh:true,consistent:false,copy:false,why:['Пришло новое подтверждение, противоречащее финальной отмене. Не отбрасываем его и не считаем повтором без проверки. Новый риск заблокирован.','New evidence conflicts with final cancellation. Do not discard it or assume duplication. New risk is blocked pending investigation.'],event:['12:03 · CONFLICT-005: итог отмены и новое исполнение требуют сверки. Резерв 8 USD — консервативный учебный снимок до разбора.','12:03 · CONFLICT-005: cancellation and new fill require reconciliation. USD 8 is the conservative synthetic reserve pending review.']},
 detached:{label:['Копирование отключено · остались позиции','Copying off · positions remain'],fill:12,reserve:0,cancelled:8,position:32,final:true,fresh:true,consistent:true,copy:false,why:['Поздняя часть принадлежит исходной сессии и управляется вручную после отключения. Новые выходы трейдера её не продают.','The late part belongs to the original session and is manually managed after detachment. New trader exits do not sell it.'],event:['12:04 · Отключить и оставить: стоимость ручных частей 32 USD. Это не прибыль и не рыночная оценка.','12:04 · Stop and keep: manual parts cost USD 32. This is neither profit nor market value.']},
 sellPartial:{label:['Продажа исполнена частично · цель сохранена','Sale partly filled · target retained'],fill:12,reserve:0,cancelled:8,position:null,final:false,fresh:true,consistent:true,copy:false,why:['Пример выхода: было 20 долей, цель — оставить 15. Проданы 2, осталось 18; сократить ещё 3. Остаток продажи ждёт подтверждения. Новую продажу параллельно не отправляем.','Exit example: 20 shares, target 15. Two sold, 18 remain; another 3 to reduce. The sale remainder awaits confirmation. No parallel sale is sent.'],event:['12:05 · SELL-005-P: подтверждены 2 доли. Цель 15 — не фактический остаток. Стоимость оставшихся частей в этом примере не рассчитана.','12:05 · SELL-005-P: 2 shares confirmed. Target 15 is not the actual remainder. Remaining cost basis is not calculated in this example.']},
 sellUnknown:{label:['Выход запрошен · итог продажи неизвестен','Exit requested · sale outcome unknown'],fill:12,reserve:0,cancelled:8,position:null,final:false,fresh:true,consistent:false,copy:false,why:['Цель закрыть всё сохранена. Предыдущая продажа ещё может исполниться: новая продажа того же исхода недоступна до сверки.','The full-exit target remains. The previous sale may still execute: no new sale of the same outcome until reconciliation.'],event:['12:05 · SELL-005: отправлена, итог неизвестен. Выделенные доли не освобождаются по тайм-ауту.','12:05 · SELL-005: submitted, outcome unknown. Allocated shares are not released on timeout.']},
 complete:{label:['Сессия окончательно сверена','Session finally reconciled'],fill:12,reserve:0,cancelled:8,position:0,final:true,fresh:true,consistent:true,copy:false,why:['Отдельный финальный учебный снимок: все части закрыты, операции окончательно сверены. История сохраняется. Новая сессия требует отдельного действия пользователя.','Separate final synthetic snapshot: all parts closed and all operations reconciled. History is retained. Starting a session requires a separate user action.'],event:['13:00 · FINAL-005: подтверждено отсутствие всех частей, резервов и расхождений. Денежный результат продажи здесь не моделируется.','13:00 · FINAL-005: no remaining parts, reserves or differences confirmed. Sale proceeds are not modelled here.']},
 stale:{label:['Нет свежих данных','Fresh evidence unavailable'],fill:null,reserve:null,cancelled:null,position:null,final:false,fresh:false,consistent:false,copy:false,why:['Последний снимок 10:20 UTC. Состояние соединения не подтверждает актуальность заявок и позиций.','Last snapshot at 10:20 UTC. Connection status does not establish current orders and positions.'],event:['12:00 · Поток не обновлялся; текущий итог неизвестен.','12:00 · Feed has not updated; current outcome is unknown.']},
 reconnected:{label:['Связь восстановлена · учёт ещё не сверён','Feed restored · ledger not reconciled'],fill:null,reserve:null,cancelled:null,position:null,final:false,fresh:true,consistent:false,copy:false,why:['Новые сообщения поступают, но расхождение REC-102 не устранено. Не исправляем сумму вручную и не включаем торговлю автоматически.','New messages arrive, but REC-102 remains unresolved. Do not overwrite amounts or automatically resume trading.'],event:['12:10 · FEED-009: связь восстановлена. Историческое расхождение остаётся открытым.','12:10 · FEED-009: connection restored. Historical difference remains open.']}
};
const tradingSets={'U-DEMO-002':['unknown'],'U-DEMO-005':['partial','late','cancelled','full','conflict','detached','sellPartial','sellUnknown','complete'],'U-DEMO-009':['stale','reconnected']};
const tradingText=pair=>actor().money?pl(...pair):pl('Подробности исполнения и суммы скрыты вашим назначением. Доступен статус; для разбора обратитесь к сотруднику с правом просмотра денежных данных.','Fill details and amounts are hidden by your assignment. Status is available; ask an employee with monetary-data access to investigate.');
function newTrading(){return {selected:{},tab:'facts',checked:{},returnOrder:false,scroll:0};}
let trading=newTrading();
function tradingAllowed(){return !!account?.logged&&actor().users&&(!actor().limited||state.userId==='U-DEMO-002');}
function tradingKey(){return trading.selected[state.userId]||tradingSets[state.userId]?.[0];}
function tradingCurrent(){return tradingAllowed()?tradingCases[tradingKey()]:null;}
function tradingChoose(key){if(!tradingAllowed()||!tradingSets[state.userId]?.includes(key))return false;trading.selected[state.userId]=key;return true;}
const tb=(ru,en,a,extra='')=>`<button type="button" class="btn" data-trading="${a}" ${extra}>${pl(ru,en)}</button>`;
const tv=v=>!actor().money?pl('Нет доступа к сумме','Amount access restricted'):v===null?pl('Не подтверждено','Unconfirmed'):fmt(v);
function tradingChecks(c){return [[c.fresh,'Данные обновлены','Evidence refreshed'],[c.consistent,'Нет необъяснённых расхождений','No unexplained differences'],[c.final,'Все операции окончательно сверены','All operations finally reconciled'],[c.reserve===0,'Нет резерва на возможное исполнение','No reserve for possible execution'],[c.position===0,'Все части сессии закрыты, включая ручные','All session parts closed, including manual parts'],[!c.copy,'Копирование прекращено','Copying stopped']];}
function tradingReview(){const c=tradingCurrent();if(!c)return '';const ready=tradingChecks(c).every(x=>x[0]);return `<section class="panel trading-review"><h2>${pl('Проверка восстановления','Recovery check')}</h2><p>${pl('Проверяется выбранный учебный снимок. Галочки определяются подтверждениями; вручную снять запрет нельзя.','Checks use the selected synthetic snapshot. Evidence determines each check; restrictions cannot be manually unchecked.')}</p><ul class="trading-checks">${tradingChecks(c).map(([ok,ru,en])=>`<li><strong>${pl(ok?'Подтверждено':'Не выполнено',ok?'Confirmed':'Not met')}</strong><span>${pl(ru,en)}</span></li>`).join('')}</ul>${tb('Проверить условия','Check conditions','check')}<div class="support-notice" role="status">${trading.checked[state.userId]===tradingKey()?pl(ready?'Условия завершения выполнены. Эта проверка не запускает новую сессию и не сбрасывает историю.':'Восстановление не разрешено: остались невыполненные условия. Продолжите сверку исходных операций.',ready?'Completion conditions met. This check neither starts a new session nor resets history.':'Recovery is not allowed: unmet conditions remain. Continue reconciling the original operations.'):pl('Проверка ещё не запускалась для этого снимка.','This snapshot has not been checked yet.')}</div><details><summary>${pl('Что происходит после остановки или технического режима?','What happens after a stop or technical mode?')}</summary><p>${pl('Отправленные операции продолжают безопасную сверку. Аварийные ограничения снимаются отдельно: владелец и другой уполномоченный сотрудник подтверждают одну область и версию проверки. Это не повторное подтверждение сделки. Неотправленные действия требуют новой проверки и подтверждения первоначального инициатора.','Submitted operations continue safe reconciliation. Emergency restrictions require separate recovery: an owner and another authorized employee confirm the same scope and check version. This is not a trade confirmation. Unsent actions need fresh checks and confirmation from the original initiator.')}</p></details>${emergencyAccess().read?eb('Аварийное восстановление','Emergency recovery','open'):''}</section>`;}
function tradingOrder(){const c=tradingCurrent();if(!c)return incidentDenied();const u=findUser(),s=findSession(),key=tradingKey(),rec=reconciliation.records.find(x=>x.uid===u.id&&x.sid===s.id);return heading(orderId(),`${u.name} · ${s.venue} · ${pl('Демо-заявка','Demo order')}`,button(t('toSession'),'session',`data-user="${u.id}" data-id="${s.id}"`))+`<section class="panel trading-selector">${feedbackSelect('trading-snapshot',pl('Учебный снимок состояния','Synthetic state snapshot'),tradingSets[u.id].map(k=>[k,pl(...tradingCases[k].label)]),key)}<p class="muted">${pl('Выбор показывает возможный исход, ничего не отправляет. Список пользователей и сверка сохраняют исходный снимок; эти варианты не заменяют его.','Selection shows a possible outcome and sends nothing. User lists and reconciliation retain their original snapshot; these variants do not replace it.')}</p></section><div class="tabs" role="group" aria-label="${pl('Раздел заявки','Order section')}">${['facts','recovery'].map(k=>`<button data-trading="tab" data-tab="${k}" aria-pressed="${trading.tab===k}" class="${trading.tab===k?'active':''}">${k==='facts'?pl('Исполнение и события','Fills and events'):pl('Восстановление','Recovery')}</button>`).join('')}</div><div class="alert"><strong>${pl(...c.label)}</strong><p>${tradingText(c.why)}</p></div>${trading.tab==='recovery'?tradingReview():`<div class="support-layout"><section class="panel"><h2>${pl('Что подтверждено','Confirmed evidence')}</h2><div class="table-wrap"><table class="trading-table"><thead><tr><th>${pl('Показатель','Measure')}</th><th>${pl('Виртуальные USD','Virtual USD')}</th></tr></thead><tbody>${[[['Исходная покупка','Original purchase'],20],[['Подтверждено по покупке','Confirmed purchase fill'],c.fill],[['Ещё может исполниться / резерв','May still fill / reserve'],c.reserve],[['Окончательно отменено','Finally cancelled'],c.cancelled],[['Стоимость всех частей сессии','Cost of all session parts'],c.position]].map(([label,value])=>`<tr><th scope="row">${pl(...label)}</th><td class="num">${tv(value)}</td></tr>`).join('')}</tbody></table></div>${actor().money&&u.id==='U-DEMO-005'?`<details><summary>${pl('Почему стоимость сессии больше исполнения?','Why can session cost exceed this fill?')}</summary><p>${pl('У Robin до заявки было 20 USD стоимости других частей. Суммы — учётная стоимость, не прибыль. Примеры не моделируют расходы площадки и рыночную переоценку; комиссия Shadow в Paper Alpha 0%.','Robin had USD 20 in other parts before this order. Amounts are cost basis, not profit. Examples do not model venue costs or mark-to-market; Shadow fee in Paper Alpha is 0%.')}</p></details>`:''}</section><section class="panel"><h2>${pl('События выбранного снимка','Selected snapshot events')}</h2><p>${u.id} · ${s.id} · ${orderId()}</p><p>${tradingText(c.event)}</p><p class="muted">${pl('Источник: синтетический сценарий','Source: synthetic scenario')} ${key}. ${pl('Это альтернативные примеры, а не часы работающего сервиса.','These are alternative examples, not a live service clock.')}</p>${rec?tb('Открыть исходную сверку '+rec.id,'Open original reconciliation '+rec.id,'reconciliation'):''}${tb('Проверить восстановление','Review recovery','recovery')}</section></div>`}`;}
function tradingReturnLink(){return trading.returnOrder&&state.route==='reconciliationItem'&&reconciliationCurrent()?.uid===state.userId?tb('Вернуться к разбору заявки','Back to order review','return'):'';}
function tradingAction(a,el){if(!tradingAllowed())return false;const c=tradingCurrent();if(!c)return false;if(a==='tab'){trading.tab=el.dataset.tab==='recovery'?'recovery':'facts';render();document.querySelector(`[data-trading="tab"][data-tab="${trading.tab}"]`)?.focus();}else if(a==='recovery'){trading.tab='recovery';render();document.querySelector('[data-trading="check"]')?.focus();}else if(a==='check'){trading.checked[state.userId]=tradingKey();render();document.querySelector('[data-trading="check"]')?.focus();}else if(a==='reconciliation'){const r=reconciliation.records.find(x=>x.uid===state.userId&&x.sid===findSession().id);if(!r||!reconciliationAllowed(r))return false;trading.returnOrder=true;trading.scroll=window.scrollY;reconciliation.id=r.id;navigate('reconciliationItem');}else if(a==='return'){trading.returnOrder=false;navigate('order');window.scrollTo(0,trading.scroll);}return true;}
document.addEventListener('click',e=>{const el=e.target.closest('[data-trading]');if(el&&!el.disabled)tradingAction(el.dataset.trading,el);});
document.addEventListener('change',e=>{if(e.target.id==='trading-snapshot'&&tradingChoose(e.target.value)){render();document.querySelector('#trading-snapshot')?.focus();}});
